make_lesson(291,"Lesson_291-the-quality-failure-matrix","The quality failure matrix","wiki.data-quality.failure-matrix","Quality failure matrix nối defect class, detection layer, containment và owner như thế nào?",(GX,IM),(GXL,IML),a(
"Matrix axes|Hàng là defect classes; cột gồm detection point, signal, impact, containment, recovery, owner và evidence.","Defect classes|Thiếu, extra, duplicate, invalid, inconsistent, stale, inaccurate và broken relationship cần tách vì recovery khác.","Detection mapping|Mỗi defect có earliest viable control và consumer-visible monitor; không giả định một test bắt mọi biến thể.","Containment mapping|Quarantine, block publish, serve stale, rollback hay notify phụ thuộc harm và recoverability.","Ownership|Producer, platform, domain steward và consumer có responsibilities khác; one owner cho decision nhưng contributors rõ.","Gap analysis|Ô trống, unknown coverage và untested recovery trở thành backlog có risk score, không tô xanh bằng assumption.")),
make_lesson(292,"Lesson_292-reliability-capstone-twenty-seeded-defects","Reliability capstone - twenty seeded defects","wiki.data-quality.capstone-seeded-defects","Capstone hai mươi seeded defects chứng minh detection, diagnosis, repair và prevention mà không lộ đáp án ra sao?",(GX,IM),(GXL,IML),a(
"Seed catalog|Hai mươi defects phủ schema, row, aggregate, relationship, temporal, orchestration, observability và publication.","Blind execution|Learner nhận symptoms và system access nhưng không nhận seed locations; evaluator giữ signed seed manifest.","Scoring layers|Chấm detection, localization, impact assessment, safe containment, repair, reconciliation và preventive control riêng.","False positives|Điểm bị trừ khi quarantine dữ liệu tốt, sửa ngoài scope hoặc claim nguyên nhân không có evidence.","Recovery proof|Sau repair phải rerun idempotently, reconcile history và chứng minh downstream consumers nhận corrected version.","Retest|Đổi ít nhất một constraint hoặc seed variant để phân biệt hiểu cơ chế với nhớ đáp án.")),
make_lesson(293,"Lesson_293-metadata-taxonomy-seven-types-and-their-authority","Metadata taxonomy - seven types and their authority","wiki.metadata.taxonomy-authority","Bảy loại metadata có authority, freshness và conflict policy khác nhau như thế nào?",(DM,),(DML,),a(
"Technical metadata|Schema, type, location và physical properties thường đến từ platform introspection nhưng có thể stale.","Operational metadata|Runs, freshness, volume, usage và failures là observations theo time window, không phải thuộc tính vĩnh viễn.","Business metadata|Definitions, grain, approved terms và policy cần accountable human authority và effective dates.","Ownership and stewardship|Owner, steward, support channel và escalation là governed assignments, không suy từ người commit gần nhất.","Quality and lineage|Assertions/results cùng dependency edges cần method, run/version và confidence để không biến inference thành fact.","Security and lifecycle|Classification, access policy, retention, status và deletion authority có thể cao hơn connector observation.")),
make_lesson(294,"Lesson_294-the-canonical-model-entities-urns-and-identity","The canonical model - entities, URNs and identity","wiki.metadata.canonical-entities-urns","Canonical metadata model giữ identity ổn định xuyên connectors, environments và rename bằng cách nào?",(DM,),(DML,),a(
"Entity boundary|Dataset, field, job, run, dashboard, glossary term và owner là entity types có lifecycle khác nhau.","Key aspect|Identity dùng platform/instance/environment/native key ổn định; display name và path không mặc nhiên là key.","URN construction|URN cần canonical encoding, namespace rules, case policy và validation để connectors không tạo twins.","Aspect separation|Schema, ownership, tags, status và usage là aspects có authority/update cadence riêng quanh cùng entity.","Alias and mapping|Cross-system equivalence cần explicit mapping với evidence/confidence; fuzzy name match không merge tự động.","Identity tests|Round-trip serialization, collision, rename, environment split và deleted/recreated object phải có expected identity.")),
make_lesson(295,"Lesson_295-relationships-versioning-rename-and-soft-deletion","Relationships, versioning, rename and soft deletion","wiki.metadata.relationships-versioning-lifecycle","Metadata graph xử lý relationship versioning, rename và soft deletion mà không mất lịch sử hay tạo ghost edge ra sao?",(DM,DL),(DML,DLL),a(
"Typed relationships|Edge có source, target, type, direction, valid/effective time và producer; generic related-to khó vận hành.","Aspect versioning|Latest state phục vụ search nhưng change log hoặc version record cần cho audit và time-aware reasoning.","Rename semantics|Rename có thể là identity-preserving alias hoặc delete/create tùy source; connector không được tự chọn khi thiếu native signal.","Soft deletion|Mark removed/status giữ identity và backlinks trong retention window; hard delete cần authority và impact check.","Edge cleanup|Khi entity mất, stale outgoing/incoming edges cần producer-scoped reconciliation để không xóa manual annotations.","Lifecycle tests|Rename, move, delete, recreate và out-of-order events được replay để kiểm search, lineage và historical trace.")),
